      kaderknop.style.top = ((k.y + k.h - v.y) * schaal + 6).toFixed(1) + 'px';
      kaderknop.style.opacity = (1 - centrumZicht) * lok;
      kaderknop.style.visibility = centrumZicht > .95 || lok < .5 ? 'hidden' : 'visible';
